-- Hindi text for the shared starter library (draft, for physio review).
-- Mirrors the "hi" blocks in assets/exercises/starter_exercises.json.

update public.exercises e
set title_hi = v.title_hi, steps_hi = v.steps_hi, move_label_hi = v.move_hi, release_label_hi = v.release_hi
from (values
  ($q$wall_squat$q$, $q$दीवार के सहारे स्क्वॉट$q$, array[$q$दीवार से पीठ सटाकर खड़े हों। पैर कूल्हों जितनी दूरी पर और दीवार से लगभग एक फ़ुट आगे रखें।$q$, $q$घुटने मोड़ते हुए धीरे-धीरे दीवार के सहारे नीचे सरकें, सिर्फ़ उतना जितना आराम से हो सके।$q$, $q$घुटनों को पैर की दूसरी उंगली की सीध में रखें।$q$, $q$इसी स्थिति में रुकें और सामान्य रूप से साँस लेते रहें।$q$, $q$धीरे-धीरे ऊपर सरककर खड़े हो जाएँ।$q$]::text[], $q$नीचे सरकें$q$, $q$ऊपर सरकें$q$),
  ($q$straight_leg_raise$q$, $q$सीधा पैर उठाना$q$, array[$q$पीठ के बल लेटें। एक घुटना मोड़कर पैर ज़मीन पर रखें और दूसरा पैर सीधा रखें।$q$, $q$सीधे पैर की जांघ की मांसपेशी को कसें।$q$, $q$सीधे पैर को मुड़े हुए घुटने की ऊँचाई तक उठाएँ।$q$, $q$रुकें, फिर धीरे-धीरे पैर ज़मीन पर रखें।$q$]::text[], $q$उठाएँ$q$, $q$नीचे लाएँ$q$),
  ($q$heel_raise$q$, $q$एड़ी उठाना$q$, array[$q$दीवार या कुर्सी की पीठ के सामने खड़े हों और संतुलन के लिए उसे हल्के से पकड़ें।$q$, $q$दोनों एड़ियाँ उठाकर पंजों पर खड़े हों।$q$, $q$ऊपर एक पल रुकें।$q$, $q$एड़ियों को धीरे-धीरे वापस ज़मीन पर लाएँ।$q$]::text[], $q$ऊपर उठें$q$, $q$धीरे से नीचे$q$),
  ($q$glute_bridge$q$, $q$ग्लूट ब्रिज (कूल्हे उठाना)$q$, array[$q$पीठ के बल लेटें, घुटने मोड़ें और पैर ज़मीन पर कूल्हों जितनी दूरी पर रखें।$q$, $q$कूल्हों की मांसपेशियाँ कसें और कूल्हे इतना उठाएँ कि कंधों से घुटनों तक शरीर सीधा हो।$q$, $q$कमर को ज़्यादा मोड़े बिना रुकें।$q$, $q$कूल्हों को धीरे-धीरे नीचे लाएँ।$q$]::text[], $q$कूल्हे उठाएँ$q$, $q$नीचे लाएँ$q$),
  ($q$clamshell$q$, $q$क्लैमशेल$q$, array[$q$करवट लेकर लेटें, कूल्हे और घुटने मोड़ें और दोनों पैर साथ रखें।$q$, $q$पैरों को आपस में मिलाए रखते हुए ऊपर वाला घुटना उठाएँ।$q$, $q$कूल्हे को पीछे की ओर लुढ़कने न दें।$q$, $q$घुटने को धीरे-धीरे नीचे लाएँ।$q$]::text[], $q$खोलें$q$, $q$बंद करें$q$),
  ($q$quad_set$q$, $q$जांघ कसना (क्वाड सेट)$q$, array[$q$बैठ जाएँ या लेट जाएँ और पैर सामने सीधा रखें।$q$, $q$जांघ के आगे की मांसपेशी कसें और घुटने के पीछे के हिस्से को नीचे दबाएँ।$q$, $q$रुकें, फिर पूरी तरह ढीला छोड़ दें।$q$]::text[], $q$कसें$q$, $q$ढीला छोड़ें$q$),
  ($q$cat_cow$q$, $q$कैट–काउ$q$, array[$q$हाथों और घुटनों के बल आएँ: हाथ कंधों के नीचे और घुटने कूल्हों के नीचे।$q$, $q$पीठ को छत की ओर गोल करें और ठुड्डी अंदर करें।$q$, $q$फिर सिर उठाते हुए पीठ को धीरे से नीचे झुकने दें।$q$, $q$धीरे-धीरे और आराम की सीमा में ही करें।$q$]::text[], $q$पीठ गोल करें$q$, $q$पीठ नीचे$q$),
  ($q$chin_tuck$q$, $q$ठुड्डी अंदर करना (चिन टक)$q$, array[$q$सीधे बैठें या खड़े हों और सामने देखें।$q$, $q$ठुड्डी को धीरे से सीधा पीछे खींचें, जैसे डबल चिन बना रहे हों।$q$, $q$आँखें सीधी रखें; सिर नीचे न झुकाएँ।$q$, $q$रुकें, फिर ढीला छोड़ें।$q$]::text[], $q$अंदर करें$q$, $q$ढीला छोड़ें$q$),
  ($q$pendulum$q$, $q$कंधे का पेंडुलम$q$, array[$q$आगे झुकें और अच्छे हाथ से मेज़ का सहारा लें।$q$, $q$दूसरे हाथ को ढीला नीचे लटकने दें।$q$, $q$शरीर को हल्का हिलाएँ ताकि हाथ छोटे-छोटे गोलों में झूले।$q$, $q$पूरे समय हाथ और कंधे को ढीला रखें।$q$]::text[], null, null),
  ($q$calf_stretch$q$, $q$पिंडली का खिंचाव$q$, array[$q$दीवार की ओर मुँह करके खड़े हों और दोनों हाथ दीवार पर रखें।$q$, $q$एक पैर पीछे ले जाएँ, उसे सीधा रखें और एड़ी ज़मीन पर टिकी रहे।$q$, $q$आगे वाला घुटना मोड़ें और आगे झुकें, जब तक पीछे वाली पिंडली में खिंचाव महसूस न हो।$q$, $q$झटके दिए बिना स्थिर रहें।$q$]::text[], null, null)
) as v(slug, title_hi, steps_hi, move_hi, release_hi)
where e.slug = v.slug and e.clinic_id is null;
